 const show=sel.dp&&sel.dp.sizes&&DPU.fsize==='i'?dpP(sel.id+'_i')||sel:sel;const cost=isKit(show)?kitCost(show):show.cost;const fc=show.price?cost/show.price*100:0;const pc=x=>x>35?'red':x>30?'warn':'ok';
